/* ---- R3: every resolution x every format ----------------------------------
 * docs/R3_MULTIMODE_PLAN.md 15-18, 23.  The types and counts are safe
 * anywhere.  Each table has ONE owner (23-9 B4, 21-2 B10):
 *   OSRDN_MODE_TABLES_SEL  resolutions and formats   osrdn_modesel.m
 *   OSRDN_MODE_TABLES_R3   FIFO words and dividers   osrdn_mode.m
 * New names on purpose -- the R2 entry took the LAST matching divider row,
 * so these must never share a table with osrdnPllRows. */

typedef struct {
    const char     *name;
    unsigned int    width, height;
    unsigned long   hTotalDisp, hSync, vTotalDisp, vSync, pitch;
    unsigned long   dotClock;           /* Hz, the refdiv 12 row */
    unsigned int    pllFirst, pllCount; /* slice of osrdnPllAll */
    unsigned long   htotalCntl;         /* HTOTAL_CNTL = htotal & 7 */
} osrdn_res_row;

typedef struct {
    const char     *token;              /* the "Display Mode" ColorSpace token */
    unsigned int    bytes;
    unsigned int    crtcFormat;         /* CRTC_GEN_CNTL bits 8-11 */
    int             ioBpp;              /* IOBitsPerPixel value */
    int             ioColorSpace;       /* IOColorSpace value */
    const char     *encoding;
    int             pseudo;             /* LUT is the window server colormap */
} osrdn_fmt_row;

typedef struct {
    unsigned long   set, clear, preserve;
} osrdn_fifo_row;

